"""Writes runtime/src/game_signatures_table.inc from signatures.json (generated by gen.py)."""
import json
from pathlib import Path
here = Path(__file__).parent
data = json.loads((here / 'signatures.json').read_text())
CODE_EXPECT = {'frameDispatch','visibilityObserver','visibilitySet','visibilityGet','internString','rebuildAppearance',
               'mergeAppearance','copyPart','releaseWrapper','destroyRecord','copyRecord','applyAppearance','frameCalls0',
               'frameCalls1','hudCall','hudSubmit','ia_build','ia_evaluate','ia_select','ia_reserve','ia_copy',
               'ia_makeLabel','ia_copyLabel','ia_focus0','ia_focus1','ia_focus2'}
WRITABLE = {'skinGlobal','loaderGlobal','emptyWrapper','emptyRecord','actorManagerGlobal','characterInfo','ia_records','ia_emptyLabel'}
CALLS = {'frameCalls0','frameCalls1','hudCall'}
rows = []
for f in data['fields']:
    n, kind = f['name'], f['kind']
    expect = 'Expect::Code' if n in CODE_EXPECT else 'Expect::Writable' if n in WRITABLE else 'Expect::ReadOnly'
    method = {'code': 'Method::Code', 'data': 'Method::Reference', 'rtti': 'Method::Rtti', 'optional': 'Method::Optional'}[kind]
    pattern = f'"{f["pattern"]}"' if 'pattern' in f else 'nullptr'
    cls = f'"{f["cls"]}"' if 'cls' in f else 'nullptr'
    rows.append(f'    {{"{n}",{method},{expect},{str(n in CALLS).lower()},{pattern},{f.get("offset",0)},{f.get("disp",0)},{f.get("end",0)},{cls},0x{f["rva"]:x}}},')
exe = data['exe']
text = ('// Generated by runtime/tools/signatures/emit.py from signatures.json. Do not edit.\n'
        f'// Source build: stamp 0x{exe["stamp"]:x}, image size 0x{exe["size"]:x}, checksum 0x{exe["checksum"]:x}.\n'
        '// Each row: field, method, where it must lie, must be a call, pattern, code offset,\n'
        '// disp32 offset, instruction end, RTTI class, address in the source build.\n'
        + '\n'.join(rows) + '\n')
out = here.parents[1] / 'src' / 'game_signatures_table.inc'
out.write_text(text, encoding='utf-8')
print(out, len(rows), 'rows')
